package com.yeyamo_mobile.api.referral_service.infrastructure.outbox;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Component;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.referral_service.application.port.ReferralOutboxPort;
@Component public class JpaReferralOutboxAdapter implements ReferralOutboxPort{private final ReferralOutboxRepository repo;private final ObjectMapper mapper;public JpaReferralOutboxAdapter(ReferralOutboxRepository r,ObjectMapper m){repo=r;mapper=m;}public void append(String type,String aggregate,String correlation,Map<String,Object>payload){try{UUID id=UUID.randomUUID();Instant now=Instant.now();Map<String,Object>event=new LinkedHashMap<>();event.put("eventId",id);event.put("eventType",type);event.put("eventVersion",1);event.put("occurredAt",now);event.put("producer","referral-service");event.put("aggregateId",aggregate);event.put("correlationId",correlation==null?id.toString():correlation);event.put("payload",payload);var e=new ReferralOutboxEvent();e.id=id;e.aggregateId=aggregate;e.eventType=type;e.payload=mapper.writeValueAsString(event);e.occurredAt=now;repo.save(e);}catch(Exception e){throw new IllegalStateException("Cannot create referral outbox event",e);}}}
